LANGUAGE_COLUMN = {'it': 0, 'es': 1}


# Returns a dialogue line in the given language. English, or a line with no translation, is returned unchanged.
def translate_line(text, language):
	if language in LANGUAGE_COLUMN and text in DIALOG_TRANSLATIONS:
		return DIALOG_TRANSLATIONS[text][LANGUAGE_COLUMN[language]]
	return text
